def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n < 10:
        return 'C'

    last_my, last_opp = history[-1]

    opp_d = 0
    for i in range(n):
        if history[i][1] == 'D':
            opp_d += 1

    recent5 = 0
    start = n - 5
    if start < 0:
        start = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            recent5 += 1

    recent3 = 0
    start = n - 3
    if start < 0:
        start = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            recent3 += 1

    recent_forgiven = 0
    recent_punished = 0
    window_start = n - 12
    if window_start < 1:
        window_start = 1
    if n > 1:
        for i in range(1, n):
            if history[i-1][0] == 'D':
                if history[i][1] == 'C':
                    if i >= window_start:
                        recent_forgiven += 1
                else:
                    if i >= window_start:
                        recent_punished += 1

    if last_opp == 'D':
        if opp_d * 10 > n * 3 or recent5 >= 4 or recent3 >= 3:
            return 'D'
        return 'C'

    if opp_d == 0 and recent_forgiven >= 1 and recent_punished == 0:
        return 'D'

    if opp_d * 10 <= n * 2 and recent_forgiven >= 1 and recent_punished == 0 and recent5 == 0:
        return 'D'

    if last_my == 'C' and last_opp == 'C' and opp_d * 10 <= n * 3 and recent5 == 0:
        if n % 20 == 0:
            return 'D'

    if last_my == 'C' and opp_d * 10 <= n and rng.random() < 0.02:
        return 'D'

    if n >= 95 and opp_d * 10 <= n * 3 and recent5 == 0 and recent_forgiven >= 1 and recent_punished == 0:
        return 'D'

    return 'C'
